import csv

def rows_for(q, accs):
    path=f'/root/{q}/COVERPAGE.tsv'
    with open(path, newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        out=[]
        for row in r:
            if row['ACCESSION_NUMBER'] in accs:
                out.append(row)
        return out

q2_accs={'0000950123-25-008361','0000950123-25-008343'}
q3_accs={'0001193125-25-282901'}

