import csv, difflib, json
from pathlib import Path

Q2_DIR=Path('/root/2025-q2')
Q3_DIR=Path('/root/2025-q3')


def best_accession(coverpage_path: Path, term: str) -> tuple[str,float,str]:
    term_l=term.lower().strip()
    best=(None, -1.0, None)
    with coverpage_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            name=(row.get('FILINGMANAGER_NAME') or '').strip()
            if not name:
                continue
            low=name.lower()
            # simple speed filter: ensure at least one term token present
            if not any(tok in low for tok in term_l.split()[:2]):
                continue
            score=difflib.SequenceMatcher(None, term_l, low).ratio()
            if score>best[1]:
                best=(row['ACCESSION_NUMBER'], score, name)
    return best  # (acc, score, name)


def summary_for(summary_path: Path, accession: str) -> dict:
    with summary_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            if row['ACCESSION_NUMBER']==accession:
                return row
    raise KeyError(f"accession not found in summary: {accession}")


def holdings_value_by_cusip(infotable_path: Path, accession: str) -> dict[str,int]:
    d={}
    with infotable_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            if row['ACCESSION_NUMBER']!=accession:
                continue
            cusip=(row.get('CUSIP') or '').strip()
            if not cusip:
                continue
            try:
                v=int(float(row.get('VALUE') or 0))
            except:
                v=0
            d[cusip]=d.get(cusip,0)+v
    return d


def top_palantir_managers(infotable_path: Path, coverpage_path: Path, palantir_cusip: str, topn=3):
    value_by_acc={}
    with infotable_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            if (row.get('CUSIP') or '').strip()!=palantir_cusip:
                continue
            acc=row['ACCESSION_NUMBER']
            try:
                v=int(float(row.get('VALUE') or 0))
            except:
                v=0
            value_by_acc[acc]=value_by_acc.get(acc,0)+v

    top_accs=sorted(value_by_acc.items(), key=lambda kv: kv[1], reverse=True)[:topn]
    acc_set={a for a,_ in top_accs}

    names={}
    with coverpage_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            acc=row['ACCESSION_NUMBER']
            if acc in acc_set:
                names[acc]=(row.get('FILINGMANAGER_NAME') or '').strip()
                if len(names)==len(acc_set):
                    break

    return [names.get(acc, acc) for acc,_ in top_accs]


# Q1 + Q2: Renaissance Technologies (Q3)
rena_acc, rena_score, rena_name = best_accession(Q3_DIR/'COVERPAGE.tsv', 'renaissance technologies')
rena_summary = summary_for(Q3_DIR/'SUMMARYPAGE.tsv', rena_acc)
q1_aum = int(rena_summary['TABLEVALUETOTAL'])
q2_count = int(rena_summary['TABLEENTRYTOTAL'])

# Q3: Berkshire Hathaway (Q2 vs Q3)
# Get best matches then choose the non-amendment for the right quarter.

def find_berkshire_accession_for_quarter(coverpage_path: Path, quarter_end: str) -> str:
    term='berkshire hathaway'
    # scan and keep best score among rows with correct quarter and not amendment
    best=(None, -1.0)
    with coverpage_path.open(newline='', encoding='utf-8', errors='ignore') as f:
        r=csv.DictReader(f, delimiter='\t')
        for row in r:
            if (row.get('REPORTCALENDARORQUARTER') or '').strip()!=quarter_end:
                continue
            if (row.get('ISAMENDMENT') or '').strip().upper()=='Y':
                continue
            name=(row.get('FILINGMANAGER_NAME') or '').strip().lower()
            if 'berkshire' not in name and 'hathaway' not in name:
                continue
            score=difflib.SequenceMatcher(None, term, name).ratio()
            if score>best[1]:
                best=(row['ACCESSION_NUMBER'], score)
    if not best[0]:
        raise RuntimeError(f"No Berkshire accession found for {quarter_end} in {coverpage_path}")
    return best[0]

berk_q2_acc = find_berkshire_accession_for_quarter(Q2_DIR/'COVERPAGE.tsv', '30-JUN-2025')
berk_q3_acc = find_berkshire_accession_for_quarter(Q3_DIR/'COVERPAGE.tsv', '30-SEP-2025')

berk_q2 = holdings_value_by_cusip(Q2_DIR/'INFOTABLE.tsv', berk_q2_acc)
berk_q3 = holdings_value_by_cusip(Q3_DIR/'INFOTABLE.tsv', berk_q3_acc)

increases=[]
for cusip, v3 in berk_q3.items():
    v2 = berk_q2.get(cusip, 0)
    diff = v3 - v2
    if diff>0:
        increases.append((diff, cusip))

increases.sort(reverse=True)
q3_top5_cusips=[cusip for _, cusip in increases[:5]]

# Q4: Palantir top managers (Q3)
palantir_cusip='69608A108'
q4_top3_names=top_palantir_managers(Q3_DIR/'INFOTABLE.tsv', Q3_DIR/'COVERPAGE.tsv', palantir_cusip, topn=3)

answers={
    'q1_answer': q1_aum,
    'q2_answer': q2_count,
    'q3_answer': q3_top5_cusips,
    'q4_answer': q4_top3_names,
}

out_path=Path('/root/answers.json')
out_path.write_text(json.dumps(answers, indent=4), encoding='utf-8')

print('Renaissance match:', rena_acc, rena_name, f'score={rena_score:.4f}')
print('Berkshire accessions:', berk_q2_acc, berk_q3_acc)
print('Top5 increases:', q3_top5_cusips)
print('Top3 Palantir managers:', q4_top3_names)
print('Wrote', out_path)
